insert into public.permissoes(codigo,descricao,ativo) values ('dialise.visualizar','Visualizar Hemodiálise',true),('dialise.gerenciar','Gerenciar Hemodiálise',true),('oncologia.visualizar','Visualizar Oncologia',true),('oncologia.gerenciar','Gerenciar Oncologia',true),('radioterapia.visualizar','Visualizar Radioterapia',true),('radioterapia.gerenciar','Gerenciar Radioterapia',true),('hemodinamica.visualizar','Visualizar Hemodinâmica',true),('hemodinamica.gerenciar','Gerenciar Hemodinâmica',true),('endoscopia.visualizar','Visualizar Endoscopia',true),('endoscopia.gerenciar','Gerenciar Endoscopia',true),('anatomia_patologica.visualizar','Visualizar Anatomia Patológica',true),('anatomia_patologica.gerenciar','Gerenciar Anatomia Patológica',true),('transplantes.visualizar','Visualizar Transplantes',true),('transplantes.gerenciar','Gerenciar Transplantes',true),('homecare.visualizar','Visualizar Home Care',true),('homecare.gerenciar','Gerenciar Home Care',true),('paliativos.visualizar','Visualizar Cuidados Paliativos',true),('paliativos.gerenciar','Gerenciar Cuidados Paliativos',true),('imunizacao.visualizar','Visualizar Imunização',true),('imunizacao.gerenciar','Gerenciar Imunização',true) on conflict(codigo) do update set descricao=excluded.descricao,ativo=true;
insert into public.perfis(empresa_id,nome,sistema,ativo) select e.id,p.nome,true,true from public.empresas e cross join (values ('Hemodialise'),('Oncologia'),('Radioterapia'),('Hemodinamica'),('Endoscopia'),('Anatomia Patologica'),('Transplantes'),('Home Care'),('Cuidados Paliativos')) p(nome) on conflict(empresa_id,nome) do update set sistema=true,ativo=true;
insert into public.perfil_permissoes(perfil_id,permissao_id) select pf.id,pm.id from public.perfis pf join public.permissoes pm on pm.ativo=true where pf.nome='Administrador' and pf.ativo=true on conflict do nothing;
insert into public.perfil_permissoes(perfil_id,permissao_id) select pf.id,pm.id from public.perfis pf join public.permissoes pm on ((pf.nome='Hemodialise' and pm.codigo like 'dialise.%') or (pf.nome='Oncologia' and pm.codigo like 'oncologia.%') or (pf.nome='Radioterapia' and pm.codigo like 'radioterapia.%') or (pf.nome='Hemodinamica' and pm.codigo like 'hemodinamica.%') or (pf.nome='Endoscopia' and pm.codigo like 'endoscopia.%') or (pf.nome='Anatomia Patologica' and pm.codigo like 'anatomia_patologica.%') or (pf.nome='Transplantes' and pm.codigo like 'transplantes.%') or (pf.nome='Home Care' and pm.codigo like 'homecare.%') or (pf.nome='Cuidados Paliativos' and pm.codigo like 'paliativos.%')) where pf.ativo=true and pm.ativo=true on conflict do nothing;
do $$ declare r record; begin for r in select * from (values ('dialise_maquinas','dialise'),('dialise_acessos','dialise'),('dialise_prescricoes','dialise'),('dialise_sessoes','dialise'),('dialise_monitoracoes','dialise'),('oncologia_planos','oncologia'),('oncologia_ciclos','oncologia'),('oncologia_quimioterapia_itens','oncologia'),('oncologia_administracoes','oncologia'),('radioterapia_planos','radioterapia'),('radioterapia_fracoes','radioterapia'),('hemodinamica_procedimentos','hemodinamica'),('endoscopia_procedimentos','endoscopia'),('anatomia_patologica_solicitacoes','anatomia_patologica'),('anatomia_patologica_amostras','anatomia_patologica'),('anatomia_patologica_laudos','anatomia_patologica'),('transplante_avaliacoes','transplantes'),('transplante_lista_espera','transplantes'),('transplante_procedimentos','transplantes'),('homecare_planos','homecare'),('homecare_visitas','homecare'),('cuidados_paliativos_planos','paliativos'),('imunizacoes','imunizacao')) x(tabela,perm) loop execute format('alter table public.%I enable row level security',r.tabela); execute format('drop policy if exists %I on public.%I',r.tabela||'_select',r.tabela); execute format('drop policy if exists %I on public.%I',r.tabela||'_write',r.tabela); execute format('create policy %I on public.%I for select to authenticated using (public.tem_unidade(empresa_id,unidade_id) and public.tem_permissao(empresa_id,unidade_id,%L))',r.tabela||'_select',r.tabela,r.perm||'.visualizar'); execute format('create policy %I on public.%I for all to authenticated using (public.tem_unidade(empresa_id,unidade_id) and public.tem_permissao(empresa_id,unidade_id,%L)) with check (public.tem_unidade(empresa_id,unidade_id) and public.tem_permissao(empresa_id,unidade_id,%L))',r.tabela||'_write',r.tabela,r.perm||'.gerenciar',r.perm||'.gerenciar'); execute format('grant select,insert,update,delete on public.%I to authenticated',r.tabela); end loop; end $$;
